insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Attivazione dinamica a coppie', 'riscaldamento', 'A coppie, corsa skip/calciata/incrociata su 15-20m con palla tra i piedi a tocchi alternati, seguita da allunghi progressivi senza palla.', 'Alzare la temperatura muscolare e attivare la coordinazione prima dell''allenamento.', 8, 22, 10, 'bassa', '20x10m per coppia', 'nessuno', 'Movimenti ampi e controllati, non cercare la velocità massima nei primi minuti.', 'Aggiungere cambi di direzione al segnale dell''allenatore.', array['riscaldamento','attivazione','coordinazione'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Torello di riscaldamento 4v1', 'riscaldamento', 'Quadrato di 8-10m di lato, 4 giocatori sui vertici scambiano palla a due tocchi, 1 al centro cerca di intercettarla.', 'Attivare gambe e attenzione con un lavoro tecnico a bassa intensità.', 5, 10, 8, 'bassa', '8x8m', 'coni per delimitare', 'Prima di ricevere, guardare dove passare (orientamento del corpo).', null, array['riscaldamento','torello','tecnica'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Slalom con guida palla', 'tecnica_individuale', 'Percorso di 6-8 coni a slalom, il giocatore conduce la palla con entrambi i piedi, poi tira o consegna al compagno successivo.', 'Migliorare il controllo di palla stretto e il cambio di piede in conduzione.', 4, 16, 10, 'media', '15m di lunghezza', '6-8 coni', 'Testa alzata il più possibile, palla vicina al piede nei cambi di direzione.', 'Ripetere a tempo, cronometrando ogni giocatore.', array['tecnica','conduzione','individuale'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Controllo orientato e cambio di direzione', 'tecnica_individuale', 'Il giocatore riceve palla da un compagno/allenatore, controlla orientando verso uno dei due lati indicati a voce e riparte in conduzione.', 'Automatizzare il primo controllo per guadagnare tempo e spazio.', 2, 12, 10, 'media', '10x10m per stazione', 'coni', 'Il controllo deve già indirizzare la palla nella direzione di gioco successiva.', 'Aumentare la velocità del passaggio in appoggio per alzare la difficoltà.', array['tecnica','controllo','individuale'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Passaggio e movimento a triangolo', 'passaggi', 'Tre giocatori ai vertici di un triangolo da 10m: si passano la palla e ogni volta chi ha passato si smarca cambiando vertice.', 'Curare precisione del passaggio e movimento senza palla per ricevere in appoggio.', 3, 9, 10, 'media', '10x10m', 'coni', 'Passaggio sul piede lontano dall''avversario immaginario, movimento immediato dopo il passaggio.', 'Limitare a un tocco per aumentare la difficoltà.', array['passaggi','movimento','tecnica'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Passaggi a due tocchi in quadrato', 'passaggi', 'Quadrato con un giocatore per lato, palla che gira sempre a due tocchi seguendo lo schema indicato dall''allenatore (diretto, incrociato, a scelta).', 'Velocità di esecuzione e qualità del primo controllo orientato al passaggio successivo.', 4, 8, 10, 'media', '12x12m', 'coni', 'Il primo tocco deve già preparare la direzione del secondo.', null, array['passaggi','tecnica','velocità'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Rondo 5v2', 'rondo', 'Cinque giocatori sul perimetro di un cerchio/quadrato da 10-12m mantengono il possesso contro due difensori centrali, a uno o due tocchi.', 'Sviluppare rapidità di pensiero, controllo sotto pressione e coordinamento tra i portatori di palla.', 7, 7, 12, 'media', '10-12m di diametro', 'coni o cerchio segnato', 'Aprire lo spazio prima di ricevere, passaggi decisi non morbidi.', 'Chi perde palla o la fa uscire entra al centro al posto di chi ha sbagliato.', array['rondo','possesso','pressione'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Rondo 6v2 a due zone', 'rondo', 'Spazio diviso in due metà, 3 attaccanti per metà (6 totali) contro 2 difensori che possono muoversi in entrambe le zone.', 'Allenare il cambio di gioco e la lettura di quando spostare il possesso da una zona all''altra.', 8, 8, 12, 'media', '20x10m', 'coni', 'Cambiare zona solo quando il passaggio è sicuro, non forzarlo sotto pressione.', null, array['rondo','possesso','cambio gioco'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Possesso palla 6v6 a tema', 'possesso', 'Due squadre da 6 in uno spazio ridotto mantengono il possesso; l''allenatore assegna un tema (es. 5 passaggi consecutivi = punto).', 'Consolidare i principi di possesso: ampiezza, appoggi, controllo del ritmo.', 12, 12, 15, 'media', '30x20m', 'pettorine, coni', 'Chi non ha palla deve offrire sempre due linee di passaggio.', 'Aggiungere jolly neutrale a favore di chi possiede.', array['possesso','ampiezza','small-sided'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Possesso a zone (3 corridoi)', 'possesso', 'Campo diviso in 3 corridoi verticali; la squadra in possesso deve toccare tutti e 3 i corridoi prima di poter concludere/segnare punto.', 'Insegnare l''uso dell''ampiezza e i cambi di gioco per superare il pressing avversario.', 10, 14, 15, 'media', '40x25m', 'coni, pettorine', 'Gli esterni devono restare larghi anche quando il gioco è dall''altra parte.', null, array['possesso','ampiezza','corridoi'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Pressing a zone su ampiezza', 'pressing', 'Partitella a tema dove la squadra senza palla deve orientare il pressing per chiudere la profondità e forzare il gioco sull''esterno.', 'Automatizzare le coperture e l''aggressione coordinata sull''esterno.', 10, 16, 15, 'alta', '30x20m', 'pettorine, porte piccole', 'Il primo che pressa chiude la linea di passaggio centrale, i compagni scalano di conseguenza.', null, array['pressing','fase difensiva','coperture'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Pressing dopo perdita palla (5 secondi)', 'pressing', 'Durante una partitella, al momento della perdita palla i 2-3 giocatori più vicini devono pressare con intensità massima per 5 secondi per tentare il recupero immediato.', 'Allenare la reazione immediata alla perdita di palla (contro-pressing).', 8, 16, 12, 'alta', '25x20m', 'pettorine, cronometro', 'I primi 5 secondi sono i più importanti: aggressività immediata, poi si rientra in blocco.', null, array['pressing','contro-pressing','transizione'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Costruzione dal basso 4v3+GK', 'costruzione', '4 difensori/centrocampisti più portiere costruiscono contro 3 attaccanti avversari che pressano per recuperare palla o forzare l''errore.', 'Migliorare la qualità di uscita palla sotto pressione, incluso l''uso del portiere come opzione.', 7, 9, 15, 'media', '30x20m con porta', 'porta, pettorine', 'Il portiere deve offrirsi come appoggio arretrato quando serve superiorità.', 'Vincolo a 2 tocchi per chi costruisce.', array['costruzione','uscita palla','portiere'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Uscita palla contro pressione', 'costruzione', 'Blocco arretrato in superiorità numerica (es. 5v3) deve superare linee di pressione avversarie disposte a zone fisse.', 'Sviluppare i tempi di passaggio e i movimenti di smarcamento per superare le linee di pressione.', 8, 8, 15, 'media', '35x20m', 'coni per le linee, pettorine', 'Chi riceve tra le linee deve girarsi verso la porta avversaria appena possibile.', null, array['costruzione','linee di pressione','possesso'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Attacco della profondità 3c2', 'attacco', '3 attaccanti contro 2 difensori più portiere: gli attaccanti devono attaccare gli spazi alle spalle della linea difensiva sfruttando la superiorità.', 'Allenare i tempi di inserimento e la scelta tra dai-e-vai, sponda o cambio di fronte.', 6, 6, 15, 'alta', '40x25m con porta', 'porta, coni', 'L''inserimento in profondità parte quando il compagno con palla alza la testa, non prima.', 'Partenza da centrocampo con passaggio filtrante iniziale dell''allenatore.', array['attacco','profondità','finalizzazione'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Sviluppo sulla fascia con cross', 'attacco', 'Esterno riceve sulla fascia, salta l''uomo o riceve in progressione, mette al centro per due attaccanti in area che attaccano primo e secondo palo.', 'Curare i tempi di inserimento in area sui cross e la qualità del traversone.', 6, 10, 12, 'media', 'metà campo', 'porta, coni, palloni extra', 'Un attaccante attacca sempre il primo palo, l''altro il secondo: mai sovrapposti.', null, array['attacco','cross','finalizzazione'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Finalizzazione da cross basso', 'finalizzazione', 'Servizio da fondocampo o da fascia con cross basso teso, 2-3 attaccanti si alternano negli inserimenti per concludere di prima.', 'Migliorare la conclusione al volo/di prima su servizi rasoterra.', 4, 10, 12, 'media', 'area di rigore e dintorni', 'porta, palloni extra', 'Corpo sopra la palla, accompagnare il tiro senza caricare troppo.', 'Alternare cross bassi e alti per variare il tipo di conclusione.', array['finalizzazione','cross','tiro'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('1c1 verso la porta', 'finalizzazione', 'Attaccante riceve palla frontale a un difensore a 20m dalla porta e deve superarlo e concludere entro un tempo limite.', 'Allenare la finta, l''accelerazione e la freddezza sotto pressione difensiva diretta.', 2, 12, 10, 'alta', '20x15m con porta', 'porta, coni', 'Accelerare nel momento del cambio di direzione, non prima.', null, array['finalizzazione','1c1','dribbling'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Contrattacco dopo recupero palla', 'transizione_offensiva', 'Partitella dove al recupero palla la squadra ha un tempo limite (es. 8 secondi) per arrivare al tiro sfruttando lo sbilanciamento avversario.', 'Automatizzare la velocità di riconoscimento e sfruttamento dello spazio in transizione.', 10, 16, 15, 'alta', '40x25m', 'pettorine, cronometro, porte', 'Primo passaggio verticale appena possibile, non ricominciare a costruire da dietro.', null, array['transizione offensiva','contrattacco','velocità'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Transizione 4c4+2 jolly', 'transizione_offensiva', '4c4 con 2 jolly neutrali che giocano sempre con chi ha appena recuperato palla, creando superiorità immediata in transizione.', 'Sfruttare la superiorità numerica nei primi secondi dopo il recupero.', 10, 10, 15, 'alta', '35x25m', 'pettorine di 3 colori', 'I jolly si smarcano subito in ampiezza per offrire un''opzione immediata.', null, array['transizione offensiva','superiorità numerica'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Riaggressione immediata dopo perdita', 'transizione_difensiva', 'Alla perdita palla in una partitella a tema, i giocatori più vicini devono riaggredire entro 3 secondi per impedire la ripartenza avversaria.', 'Ridurre il tempo di reazione alla perdita di palla, prevenendo il contrattacco avversario.', 8, 16, 12, 'alta', '30x20m', 'pettorine, cronometro', 'Chi perde palla è il primo a riaggredire, non aspettare i compagni.', null, array['transizione difensiva','riaggressione'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Ripiegamento numerico 3c2', 'transizione_difensiva', '3 attaccanti ripartono in superiorità contro 2 difensori che devono ripiegare da posizione svantaggiata e ritardare fino all''arrivo di un terzo compagno.', 'Allenare il ripiegamento, la scelta dei tempi di intervento e il temporeggiamento in inferiorità.', 6, 6, 12, 'alta', '40x25m con porta', 'porta, coni', 'Il difensore più arretrato guida i tempi, l''altro chiude la linea di passaggio più pericolosa.', null, array['transizione difensiva','ripiegamento','inferiorità'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Marcatura e diagonali difensive', 'difesa', 'Blocco di 4 difensori si muove in scivolamento laterale seguendo il movimento della palla tra appoggi esterni, mantenendo le diagonali di copertura.', 'Automatizzare i movimenti di reparto e le coperture reciproche.', 5, 8, 12, 'media', '30x15m', 'coni', 'Chi è più vicino alla palla pressa, gli altri scalano in diagonale, mai in linea piatta.', null, array['difesa','reparto','coperture'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Difesa dell''area su cross', 'difesa', 'Difensori e portiere lavorano su letture di cross ripetuti da entrambe le fasce, alternando anticipo, respinta e presa alta del portiere.', 'Migliorare tempi di attacco alla palla su palle alte in area.', 5, 9, 12, 'media', 'area di rigore', 'porta, palloni extra', 'Attaccare la palla, non aspettarla: il primo movimento è sempre verso il pallone.', null, array['difesa','cross','portiere'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Superiorità 4c2 in ampiezza', 'superiorita_numerica', '4 giocatori larghi contro 2 difensori in uno spazio ampio, obiettivo attraversare una linea di meta opposta palla al piede o con passaggio.', 'Sfruttare rapidamente la superiorità numerica con ampiezza e velocità di esecuzione.', 6, 6, 12, 'media', '30x15m', 'coni', 'Allargare subito il campo per allungare la distanza tra i due difensori.', null, array['superiorità numerica','ampiezza'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('3c1 a tutto campo', 'superiorita_numerica', '3 attaccanti contro 1 difensore su tutta la lunghezza del campo, con obiettivo arrivare al tiro sfruttando triangolazioni rapide.', 'Automatizzare le triangolazioni rapide in ampia superiorità numerica.', 4, 4, 10, 'alta', 'tutto il campo o metà campo', 'porta', 'Non concentrare tutti e tre sulla palla: chi è lontano dalla linea di passaggio si allarga.', null, array['superiorità numerica','triangolazioni'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Inferiorità 3c4 con ripiegamento', 'inferiorita_numerica', '3 difensori devono contenere 4 attaccanti partendo da una posizione arretrata, privilegiando il raddoppio sulla palla e la copertura centrale.', 'Allenare organizzazione e sacrificio in inferiorità numerica.', 7, 7, 12, 'alta', '35x25m con porta', 'porta, coni', 'Mai lasciare campo libero centralmente: meglio concedere l''esterno che il centro dell''area.', null, array['inferiorità numerica','difesa','organizzazione'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Difesa in dieci dopo espulsione (simulata)', 'inferiorita_numerica', 'Partitella 11v10 (o proporzionale) dove la squadra in inferiorità lavora su compattezza tra i reparti e gestione degli spazi concessi.', 'Simulare la gestione di una condizione di inferiorità numerica prolungata.', 14, 22, 15, 'media', 'campo ridotto', 'pettorine, porte', 'Restare compatti tra i reparti anche a costo di rinunciare a pressare alto.', null, array['inferiorità numerica','compattezza'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Partitella 4c4 a porte piccole', 'small_sided_game', '4c4 su campo ridotto con 2-4 porte piccole per squadra, senza portieri, per stimolare decisioni rapide e ampio coinvolgimento tecnico.', 'Aumentare le ripetizioni tecniche individuali e la presa di decisione in spazi stretti.', 8, 8, 15, 'alta', '25x18m', 'porte piccole o coni, pettorine', 'Premiare la scelta rapida rispetto al controllo prolungato del pallone.', 'Vincolo a 2 tocchi per aumentare la velocità di gioco.', array['small-sided game','decisione','tecnica'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Partitella 5c5 con jolly esterni', 'small_sided_game', '5c5 con 2 jolly sulle fasce che giocano sempre a favore della squadra in possesso, offrendo sempre un''opzione di ampiezza.', 'Allenare l''uso dell''ampiezza in un contesto di gioco reale a effettivo ridotto.', 10, 12, 18, 'alta', '35x22m', 'porte, pettorine', 'I jolly restano sempre larghi, non entrano mai nel gioco centrale.', null, array['small-sided game','ampiezza','jolly'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Partita a tema: massimo 2 tocchi', 'partita_a_tema', 'Partita normale (8c8 o simile) con vincolo di massimo 2 tocchi a giocatore per stimolare velocità di gioco e qualità del primo controllo.', 'Velocizzare la circolazione palla e migliorare la qualità del controllo orientato in game reale.', 12, 18, 20, 'alta', 'mezzo campo o campo intero ridotto', 'porte, pettorine', 'Chi riceve deve già sapere dove giocherà il secondo tocco prima ancora di controllare.', 'Togliere il vincolo negli ultimi 5 minuti per il transfer libero.', array['partita a tema','velocità di gioco','vincolo tocchi'], true);
insert into exercises (name, category, description, objective, players_min, players_max, duration_minutes, intensity, field_size, equipment, coaching_points, variants, tags, is_template) values ('Partita a tema: gol solo di prima', 'partita_a_tema', 'Partita normale dove i gol sono validi solo se realizzati con conclusione al volo o di prima intenzione.', 'Stimolare gli inserimenti in area e la prontezza nella conclusione senza controllo preventivo.', 12, 18, 20, 'alta', 'campo ridotto', 'porte, pettorine', 'Anticipare il movimento in area prima che arrivi il cross, non dopo.', null, array['partita a tema','finalizzazione','inserimenti'], true);
